import{_ as o,a0 as l,w as d,s as r,ao as p,I as n,x as s,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Linux 中刪除文本中的回車字符 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中刪除文本中的回車字符 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中刪除文本中的回車字符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中刪除文本中的回車字符 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190918 How to remove carriage returns from text files on Linux","title":"如何在 Linux 中刪除文本中的回車字符","tag":"201909","desc":""},"relativePath":"201909/20190918 How to remove carriage returns from text files on Linux.md","filePath":"[post].md"}'),c={name:"201909/20190918 How to remove carriage returns from text files on Linux.md"};function h(u,e,g,k,f,x){const t=l("Link");return d(),r("div",null,[e[15]||(e[15]=p(`<h1 id="如何在-linux-中刪除文本中的回車字符" tabindex="-1">如何在 Linux 中刪除文本中的回車字符 <a class="header-anchor" href="#如何在-linux-中刪除文本中的回車字符" aria-label="Permalink to “如何在 Linux 中刪除文本中的回車字符”">​</a></h1><blockquote><p>當回車字符（<code>Ctrl+M</code>）讓你緊張時，別擔心。有幾種簡單的方法消除它們。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201909/25/214211xenk2dqfepx3xemm.jpg" alt=""></p><p>“回車”字符可以往回追溯很長一段時間 —— 早在打字機上就有一個機械裝置或槓桿將承載紙滾筒的機架移到右邊，以便可以重新在左側輸入字母。他們在 Windows 上的文本文件上保留了它，但從未在 Linux 系統上使用過。當你嘗試在 Linux 上處理在 Windows 上創建的文件時，這種不兼容性有時會導致問題，但這是一個非常容易解決的問題。</p><p>如果你使用 <code>od</code>（<ruby>八進制轉儲<rt>octal dump</rt></ruby>）命令查看文件，那麼回車（也用 <code>Ctrl+M</code> 代表）字符將顯示為八進制的 15。字符 <code>CRLF</code> 通常用於表示 Windows 文本文件中的一行結束的回車符和換行符序列。那些注意看八進制轉儲的會看到 <code>\\r\\n</code>。相比之下，Linux 文本僅以換行符結束。</p><p>這有一個 <code>od</code> 輸出的示例，高亮顯示了行中的 <code>CRLF</code> 字符，以及它的八進制。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ od -bc testfile.txt</span></span>
<span class="line"><span>0000000 124 150 151 163 040 151 163 040 141 040 164 145 163 164 040 146</span></span>
<span class="line"><span>          T   h   i   s       i   s       a       t   e   s   t       f</span></span>
<span class="line"><span>0000020 151 154 145 040 146 162 157 155 040 127 151 156 144 157 167 163</span></span>
<span class="line"><span>          i   l   e       f   r   o   m       W   i   n   d   o   w   s</span></span>
<span class="line"><span>0000040 056 015 012 111 164 047 163 040 144 151 146 146 145 162 145 156  &lt;==</span></span>
<span class="line"><span>          .  \\r  \\n   I   t   &#39;   s       d   i   f   f   e   r   e   n  &lt;==</span></span>
<span class="line"><span>0000060 164 040 164 150 141 156 040 141 040 125 156 151 170 040 164 145</span></span>
<span class="line"><span>          t       t   h   a   n       a       U   n   i   x       t   e</span></span>
<span class="line"><span>0000100 170 164 040 146 151 154 145 015 012 167 157 165 154 144 040 142  &lt;==</span></span>
<span class="line"><span>          x   t       f   i   l   e  \\r  \\n   w   o   u   l   d       b  &lt;==</span></span></code></pre></div><p>雖然這些字符不是大問題，但是當你想要以某種方式解析文本，並且不希望就它們是否存在進行編碼時，這有時候會產生干擾。</p><h3 id="_3-種從文本中刪除回車符的方法" tabindex="-1">3 種從文本中刪除回車符的方法 <a class="header-anchor" href="#_3-種從文本中刪除回車符的方法" aria-label="Permalink to “3 種從文本中刪除回車符的方法”">​</a></h3><p>幸運的是，有幾種方法可以輕鬆刪除回車符。這有三個選擇：</p><h4 id="dos2unix" tabindex="-1">dos2unix <a class="header-anchor" href="#dos2unix" aria-label="Permalink to “dos2unix”">​</a></h4><p>你可能會在安裝時遇到麻煩，但 <code>dos2unix</code> 可能是將 Windows 文本轉換為 Unix/Linux 文本的最簡單方法。一個命令帶上一個參數就行了。不需要第二個文件名。該文件會被直接更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dos2unix testfile.txt</span></span>
<span class="line"><span>dos2unix: converting file testfile.txt to Unix format...</span></span></code></pre></div><p>你應該會發現文件長度減少，具體取決於它包含的行數。包含 100 行的文件可能會縮小 99 個字符，因為只有最後一行不會以 <code>CRLF</code> 字符結尾。</p><p>之前：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r--   1 shs  shs        121 Sep 14 19:11 testfile.txt</span></span></code></pre></div><p>之後：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r--   1 shs  shs        118 Sep 14 19:12 testfile.txt</span></span></code></pre></div><p>如果你需要轉換大量文件，不用每次修復一個。相反，將它們全部放在一個目錄中並運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type f -exec dos2unix {} \\;</span></span></code></pre></div><p>在此命令中，我們使用 <code>find</code> 查找常規文件，然後運行 <code>dos2unix</code> 命令一次轉換一個。命令中的 <code>{}</code> 將被替換為文件名。運行時，你應該處於包含文件的目錄中。此命令可能會損壞其他類型的文件，例如除了文本文件外在上下文中包含八進制 15 的文件（如，鏡像文件中的字節）。</p><h4 id="sed" tabindex="-1">sed <a class="header-anchor" href="#sed" aria-label="Permalink to “sed”">​</a></h4><p>你還可以使用流編輯器 <code>sed</code> 來刪除回車符。但是，你必須提供第二個文件名。以下是例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -e “s/^M//” before.txt &gt; after.txt</span></span></code></pre></div><p>一件需要注意的重要的事情是，請不要輸入你看到的字符。你必須按下 <code>Ctrl+V</code> 後跟 <code>Ctrl+M</code> 來輸入 <code>^M</code>。<code>s</code> 是替換命令。斜槓將我們要查找的文本（<code>Ctrl + M</code>）和要替換的文本（這裏為空）分開。</p><h4 id="vi" tabindex="-1">vi <a class="header-anchor" href="#vi" aria-label="Permalink to “vi”">​</a></h4><p>你甚至可以使用 <code>vi</code> 刪除回車符（<code>Ctrl+M</code>），但這裏假設你沒有打開數百個文件，或許也在做一些其他的修改。你可以鍵入 <code>:</code> 進入命令列，然後輸入下面的字符串。與 <code>sed</code> 一樣，命令中 <code>^M</code> 需要通過 <code>Ctrl+V</code> 輸入 <code>^</code>，然後 <code>Ctrl+M</code> 插入 <code>M</code>。<code>%s</code> 是替換操作，斜槓再次將我們要刪除的字符和我們想要替換它的文本（空）分開。 <code>g</code>（全局）意味在所有行上執行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:%s/^M//g</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><code>dos2unix</code> 命令可能是最容易記住的，也是從文本中刪除回車的最可靠的方法。其他選擇使用起來有點困難，但它們提供相同的基本功能。</p><hr>`,31)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(t,{href:"https://www.networkworld.com/article/3438857/how-to-remove-carriage-returns-from-text-files-on-linux.html"},{default:a(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3438857/how-to-remove-carriage-returns-from-text-files-on-linux.html",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),i(t,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:a(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:a(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const w=o(c,[["render",h]]);export{C as __pageData,w as default};
